import { chromium } from "/home/diogenes/Projects/apps/twyne-ink/node_modules/playwright/index.mjs";
for (const args of [
  ["--enable-unsafe-webgpu", "--enable-features=Vulkan", "--use-angle=vulkan"],
  ["--enable-unsafe-webgpu", "--enable-features=Vulkan,VulkanFromANGLE", "--use-vulkan=native", "--ignore-gpu-blocklist"],
]) {
  const b = await chromium.launch({ headless: true, args });
  const p = await b.newPage();
  await p.goto("about:blank");
  const r = await p.evaluate(async () => {
    if (!navigator.gpu) return "no navigator.gpu";
    const a = await navigator.gpu.requestAdapter();
    if (!a) return "no adapter";
    const info = a.info ?? {};
    return JSON.stringify({ vendor: info.vendor, arch: info.architecture, desc: info.description, fallback: info.isFallbackAdapter });
  });
  console.log(args.join(" "), "=>", r);
  await b.close();
}
EOF
env -u LD_LIBRARY_PATH timeout 90 node probe.mjs

