 * same --doc-pad-* custom properties that drive the page padding, so moving
 * the layout sliders moves the guides. Painted as the page's own background
 * so they always sit behind the text without any z-index juggling. */
      paginationActive: false,
      toolbarTab: DEFAULT_COMPOSITOR_TAB,
    });

    useStyles$(`
    .twyne-editor {
      min-height: 100%;
    }
    /* Zen mode: quiet the manuscript down to plain text while writing.
       The marks (and their data) are untouched — only the visual
       highlighting and hover previews are suppressed, so nothing is lost
       on toggle-off. */
    .twyne-editor.zen-mode .twyne-persona-note {
      background: none !important;
      border-bottom: none !important;
      animation: none !important;
      cursor: text;
    }
    .twyne-editor.zen-mode .ProseMirror .twyne-comment-mark {
      background: none !important;
      border-bottom: none !important;
