/* ── Wet ink ────────────────────────────────────────────────────────
 * WebGPU canvases from src/utils/ink. A page band lives beneath the
 * text of an isolated host, so it paints on the page and under letters;
 * a moment sits over (or under) a few words for one effect and is
 * removed once dry. None of them take pointer events. */
.ink-page-host {
  isolation: isolate;
}
.ink-page-band {
  position: absolute;
  left: 0;
  top: 0;
  z-index: -1;
  pointer-events: none;
}
.ink-moment {
  position: absolute;
  z-index: 5;
  pointer-events: none;
}
.ink-moment--under {
  z-index: 0;
}

/* The proof comes back with nothing left to answer. */
.clean-proof-stamp {
  --stamp-rotation: -7deg;
  position: relative;
  display: block;
  width: 9.5rem;
  aspect-ratio: 1;
  color: var(--color-vermilion);
  transform: rotate(var(--stamp-rotation));
  pointer-events: none;
}
.clean-proof-stamp__mark {
  position: absolute;
  inset: 0;
  display: grid;
  place-content: center;
  gap: 0.1rem;
  border: 3px solid currentColor;
  border-radius: 50%;
  outline: 1px solid currentColor;
  outline-offset: -9px;
  font-family: var(--font-typewriter);
  text-align: center;
  text-transform: uppercase;
  letter-spacing: 0.14em;
  line-height: 1.05;
}
.clean-proof-stamp__mark b {
  font-family: var(--font-display);
  font-size: 1.3rem;
  letter-spacing: 0.06em;
}
.clean-proof-stamp__mark small {
  font-size: 0.6rem;
}
