        await wait(42 + Math.random() * 55 + pause);
      }
    });
    return (
      <div
        ref={host}
        class="paper-sheet ink-page-host relative min-h-[9.5rem] px-6 py-5"
      >
        <p
          ref={line}
          class="text-[1.125rem] leading-[1.8]"
          style="font-family: var(--font-serif)"
        />
      </div>
    );
  },
);

/** Accepting a proposed edit: struck words give way to the new ones. */
export const AcceptDemo = component$<{ ink: boolean; replay: number }>(
  (props) => {
    const host = useSignal<HTMLDivElement>();
    const target = useSignal<HTMLSpanElement>();
    const stamp = useSignal(0);
    const state = useStore({ accepted: false });
    // eslint-disable-next-line qwik/no-use-visible-task
    useVisibleTask$(async ({ track }) => {
      track(() => props.replay);
      const el = host.value;
      const span = target.value;
      if (!el || !span) return;
      state.accepted = false;
      span.textContent = "voted in favour of approving";
      await wait(700);
      if (props.ink) {
        const range = document.createRange();
        range.selectNodeContents(span);
        await inkStrike(el, lineRects(range));
        await wait(320);
      }
      state.accepted = true;
      span.textContent = "approved";
      stamp.value++;
      if (props.ink) {
        await new Promise((r) => requestAnimationFrame(r));
        const range = document.createRange();
        range.selectNodeContents(span);
        await inkReveal(el, lineRects(range));
      }
    });
    return (
      <div
        ref={host}
        class="paper-sheet relative min-h-[9.5rem] overflow-hidden px-6 py-5"
      >
        <p
          class="text-[1.125rem] leading-[1.8]"
          style="font-family: var(--font-serif)"
        >
          After a long night the committee{" "}
          <span ref={target} class={{ "twyne-suggestion": !state.accepted }}>
            voted in favour of approving
          </span>{" "}
          the measure.
        </p>
        {stamp.value > 0 && (
          <div
            key={stamp.value}
            class="lab-approval-stamp pointer-events-none absolute right-3 top-1 w-24"
          >
            <WorkflowStamp kind="revised" impressionKey={stamp.value} />
          </div>
        )}
      </div>
    );
  },
);

const NOTES = [
  "Is “rumour” doing too much here?",
  "Cite the ferry timetable.",
  "Lovely — keep this.",
];

/** The margin empties, and the proof is stamped clean. */
export const CleanProofDemo = component$<{ ink: boolean; replay: number }>(
  (props) => {
    const host = useSignal<HTMLDivElement>();
    const slot = useSignal<HTMLDivElement>();
    const state = useStore({ open: NOTES.length, stamped: 0 });
    // eslint-disable-next-line qwik/no-use-visible-task
    useVisibleTask$(async ({ track }) => {
      track(() => props.replay);
      state.open = NOTES.length;
      state.stamped = 0;
      await wait(600);
      for (let i = NOTES.length; i > 0; i--) {
        state.open = i - 1;
        await wait(380);
      }
      state.stamped = props.replay + 1;
      if (!props.ink) return;
      // The die meets the paper about a third of the way through its press.
      await new Promise((r) => requestAnimationFrame(r));
      const tool = slot.value?.querySelector<HTMLImageElement>(".ink-stamp__tool");
      if (tool && !tool.complete) {
        await new Promise((r) => tool.addEventListener("load", r, { once: true }));
      }
      await wait(160);
      const el = host.value;
      const mark = slot.value?.querySelector(".clean-proof-stamp__mark");
      if (el && mark) await inkStampPool(el, mark.getBoundingClientRect());
    });
    return (
      <div
        ref={host}
        class="paper-sheet relative grid min-h-[13rem] grid-cols-[1fr_9rem] gap-4 overflow-hidden px-6 py-5"
      >
        <p
          class="text-[1.05rem] leading-[1.8]"
          style="font-family: var(--font-serif)"
        >
          The ferry left at dawn, and by the time the fog lifted the harbour
          was a rumour behind us.
        </p>
        <div class="relative">
          {NOTES.map((note, i) => (
            <p
              key={note}
              class="mb-2 rounded-sm border border-[color:var(--color-paper-3)] bg-[color:var(--color-paper-soft)] px-2 py-1 text-xs transition-all duration-300"
              style={{
                opacity: i < state.open ? 1 : 0,
                transform: i < state.open ? "none" : "translateX(1.5rem)",
              }}
            >
              {note}
            </p>
          ))}
          <div
            ref={slot}
            class="absolute left-1/2 top-1/2 -translate-x-1/2 -translate-y-1/2"
          >
            {state.stamped > 0 && (
              <CleanProofStamp impressionKey={state.stamped} />
            )}
          </div>
        </div>
      </div>
    );
  },
);

export const InkSideBySide = component$(() => {
  const typing = useSignal(0);
  const accept = useSignal(0);
  const proof = useSignal(0);
  return (
    <div class="p-8" style="max-width: 72rem">
      <div class="mb-6 flex items-center gap-4">
        <h2 class="text-2xl" style="font-family: var(--font-display)">
          Ink, side by side
        </h2>
        <button
          class="btn-press"
          onClick$={() => {
            typing.value++;
            accept.value++;
            proof.value++;
          }}
        >
          Replay all
        </button>
      </div>
      <InkStatsReadout />
      <InkPair
        title="Typing"
        note="Each letter leaves a faint wet halo that soaks along the grain and dries back into the page. The text itself never moves."
      >
        <button q:slot="actions" class="btn-paper" onClick$={() => typing.value++}>
          Replay
        </button>
        <TypingDemo q:slot="before" ink={false} replay={typing.value} />
        <TypingDemo q:slot="after" ink replay={typing.value} />
      </InkPair>
      <InkPair
        title="Accepting a suggestion"
        note="The strike wicks along the old words, then the new words soak up through the page as the wet front reaches them."
      >
        <button q:slot="actions" class="btn-paper" onClick$={() => accept.value++}>
          Replay
        </button>
        <AcceptDemo q:slot="before" ink={false} replay={accept.value} />
        <AcceptDemo q:slot="after" ink replay={accept.value} />
      </InkPair>
      <InkPair
        title="Clean proof"
        note="When the last note is answered, the stamp comes down. With ink, the die squeezes a pooled rim and a little spatter out from under itself."
      >
        <button q:slot="actions" class="btn-paper" onClick$={() => proof.value++}>
          Replay
        </button>
        <CleanProofDemo q:slot="before" ink={false} replay={proof.value} />
        <CleanProofDemo q:slot="after" ink replay={proof.value} />
      </InkPair>
    </div>
  );
});

/** Live engine numbers: what this device spends on the ink. */
export const InkStatsReadout = component$(() => {
  const stats = useStore<InkStats & { available: boolean | null }>({
    available: null,
    adapter: "",
    fps: 0,
    cpuMs: 0,
    gpuMs: null,
    awake: 0,
    economy: false,
  });
  // eslint-disable-next-line qwik/no-use-visible-task
  useVisibleTask$(async ({ cleanup }) => {
    const engine = await inkEngine();
    stats.available = !!engine;
    if (!engine) return;
    engine.measure = true;
    const timer = setInterval(() => Object.assign(stats, engine.stats), 250);
    cleanup(() => {
      clearInterval(timer);
      engine.measure = false;
    });
  });
  return (
    <p
      class="ink-lab-stats mb-6 font-[family-name:var(--font-typewriter)] text-xs text-[color:var(--color-ink-muted)]"
      data-available={String(stats.available)}
    >
      {stats.available === null
        ? "Starting the ink engine…"
        : stats.available
          ? `${stats.adapter} · ${stats.awake ? `${stats.fps.toFixed(0)} fps` : "asleep"} · CPU ${stats.cpuMs.toFixed(2)} ms · GPU ${stats.gpuMs === null ? "n/a" : `${stats.gpuMs.toFixed(2)} ms`}${stats.economy ? " · economy" : ""}`
          : "WebGPU is unavailable here, or ink is switched off: the After column shows the plain fallback."}
    </p>
  );
});

type ToolName = "drop" | "strike" | "bleed" | "stamp";

/** Tune a preset by hand on a scratch sheet, and type into it. */
export const InkPlayground = component$(() => {
  const host = useSignal<HTMLDivElement>();
  const sheet = useSignal<HTMLDivElement>();
  const editable = useSignal<HTMLDivElement>();
  const surface = useSignal<NoSerialize<InkSurface>>();
  const state = useStore<{
    preset: InkPreset;
    tuning: InkTuning;
    tool: ToolName;
    economy: boolean;
  }>({
    preset: "typing",
    tuning: { ...INK_PRESETS.typing },
    tool: "drop",
    economy: false,
  });

  // eslint-disable-next-line qwik/no-use-visible-task
  useVisibleTask$(async ({ cleanup }) => {
    const el = sheet.value;
    const typing = host.value;
    const input = editable.value;
    if (!el || !typing || !input) return;
    const engine = await inkEngine();
    if (!engine) return;
    const canvas = document.createElement("canvas");
    canvas.className = "ink-page-band";
    canvas.style.width = "100%";
    canvas.style.height = "100%";
    el.prepend(canvas);
    const s = engine.surface(canvas, state.tuning);
    s.resize(el.clientWidth, el.clientHeight);
    s.readColors(el, "var(--color-ink)");
    surface.value = noSerialize(s);
    const page = await attachPageInk(typing, () => {
      const sel = window.getSelection();
      if (!sel?.rangeCount) return null;
      const box = sel.getRangeAt(0).getBoundingClientRect();
      return box.height ? box : null;
    });
    const onInput = (e: Event) => isTypedInput(e) && page?.keystroke();
    input.addEventListener("input", onInput);
    cleanup(() => {
      input.removeEventListener("input", onInput);
      page?.destroy();
      s.destroy();
      canvas.remove();
    });
  });

  // eslint-disable-next-line qwik/no-use-visible-task
  useVisibleTask$(({ track }) => {
    const tuning = { ...track(() => state.tuning) };
    for (const key of Object.keys(tuning) as (keyof InkTuning)[]) {
      track(() => state.tuning[key]);
    }
    const s = surface.value;
    const el = sheet.value;
    if (!s || !el) return;
    const resized = s.tuning.cellPx !== tuning.cellPx;
    s.tuning = tuning;
    if (resized) s.resize(el.clientWidth, el.clientHeight);
  });

  // eslint-disable-next-line qwik/no-use-visible-task
  useVisibleTask$(({ track, cleanup }) => {
    if (!track(() => state.economy)) return;
    cleanup(holdInkEconomy());
  });

  return (
    <div class="grid gap-6 p-8 lg:grid-cols-[18rem_1fr]" style="max-width: 76rem">
      <aside class="space-y-3 text-sm">
        <InkStatsReadout />
        <label class="block">
          Preset
          <select
            class="ml-2"
            value={state.preset}
            onChange$={(_, el) => {
              state.preset = el.value as InkPreset;
              state.tuning = { ...INK_PRESETS[state.preset] };
            }}
          >
            {(Object.keys(INK_PRESETS) as InkPreset[]).map((p) => (
              <option key={p} value={p}>
                {p}
              </option>
            ))}
          </select>
        </label>
        {(Object.keys(INK_TUNING_RANGES) as (keyof InkTuning)[]).map((key) => {
          const range = INK_TUNING_RANGES[key]!;
          return (
            <label key={key} class="block">
              <span class="flex justify-between">
                <span>{key}</span>
                <span class="tabular-nums">{state.tuning[key]}</span>
              </span>
              <input
                type="range"
                class="w-full"
                min={range.min}
                max={range.max}
                step={range.step}
                value={state.tuning[key]}
                onInput$={(_, el) => {
                  state.tuning = { ...state.tuning, [key]: Number(el.value) };
                }}
              />
            </label>
          );
        })}
        <label class="flex items-center gap-2">
          <input
            type="checkbox"
            checked={state.economy}
            onChange$={(_, el) => (state.economy = el.checked)}
          />
          Economy (as while Live voice runs)
        </label>
      </aside>
      <div class="space-y-4">
        <div class="flex flex-wrap gap-2">
          {(["drop", "strike", "bleed", "stamp"] as ToolName[]).map((tool) => (
            <button
              key={tool}
              class={state.tool === tool ? "btn-press" : "btn-paper"}
              onClick$={() => (state.tool = tool)}
            >
              {tool}
            </button>
          ))}
          <button class="btn-paper" onClick$={() => surface.value?.clear()}>
            Dry it all
          </button>
        </div>
        <div
          ref={sheet}
          class="paper-sheet ink-page-host relative h-[22rem] cursor-crosshair overflow-hidden"
          onPointerDown$={(e, el) => {
            const s = surface.value;
            if (!s) return;
            const box = el.getBoundingClientRect();
            const x = e.clientX - box.left;
            const y = e.clientY - box.top;
            if (state.tool === "drop") {
              s.drop({ x, y, radius: 14, water: 1.2, pigment: 0.25, ragged: 0.7 });
            } else if (state.tool === "strike") {
              s.stroke({ x, y }, { x: x + 220, y }, 360, {
                radius: 1.6,
                water: 1.3,
                pigment: 0.55,
              });
            } else if (state.tool === "bleed") {
              s.bleed({ x, y: y - 12, width: 180, height: 24 });
            } else {
              s.splatter({ x, y, count: 120, speed: 3.2, mass: 0.5 });
            }
          }}
        >
          <p class="pointer-events-none select-none p-4 text-xs text-[color:var(--color-ink-muted)]">
            Click to use the tool on a scratch sheet.
          </p>
        </div>
        <div
          ref={host}
          class="paper-sheet ink-page-host relative min-h-[10rem] px-6 py-5"
        >
          <div
            ref={editable}
            contentEditable="true"
            class="min-h-[8rem] text-[1.125rem] leading-[1.8] outline-none"
            style="font-family: var(--font-serif)"
          >
            Type here to feel the typing preset.
          </div>
        </div>
      </div>
    </div>
  );
});

