// ragged contact line, not a blur. `rag` roughens it along the fibers.
fn contact(value: f32, threshold: f32, rag: f32) -> f32 {
  let v = value + rag;
  let aa = max(fwidth(v), 1e-4) * 0.75;
  return smoothstep(threshold - aa, threshold + aa, v);
}

@fragment
fn fs(in: VertexOut) -> @location(0) vec4f {
  let s = textureSample(field, fieldSampler, in.uv);
  let fiber = textureSample(fibers, fiberSampler, in.uv * params.fiberScale + params.fiberOffset);
  let rag = (fiber.r - 0.5) * params.grain;
  let tooth = mix(1.0 - params.grain * 0.6, 1.0 + params.grain * 0.6, fiber.r);

  // Neighbouring water, for both the glint and the meniscus at the edge.
  let dx = textureSample(field, fieldSampler, in.uv + vec2f(params.texel.x, 0.0)).x
    - textureSample(field, fieldSampler, in.uv - vec2f(params.texel.x, 0.0)).x;
  let dy = textureSample(field, fieldSampler, in.uv + vec2f(0.0, params.texel.y)).x
    - textureSample(field, fieldSampler, in.uv - vec2f(0.0, params.texel.y)).x;

  let water = s.x;
  let pigment = s.y * 0.7 + s.z;
  let wet = contact(water, 0.05, rag * 0.08) * params.sheen;
  let stained = contact(pigment, 0.012, rag * 0.02);
  // Inside the stain the density follows the pigment, never dropping to a
  // wash so thin it reads as a tint rather than ink.
  let density = stained * (0.08 + pigment * params.strength) * tooth;

  // Under the stain: the cover (while revealing) or the page itself.
  let revealed = contact(s.w, 0.5, rag * 0.6);
  let showCover = params.revealing * (1.0 - revealed) * (1.0 - params.lift);
  let ground = mix(params.paper, params.cover, showCover);

  // Wet paper loses the air between its fibers and darkens.
  let soaked = mix(ground, ground * select(0.9, 1.1, params.dark > 0.5), wet);
  var color = pigmentOver(soaked, params.ink, density);

  // A thin glint off standing water, lit from the upper left.
  let normal = normalize(vec3f(-dx * 4.0, -dy * 4.0, 1.0));
  let glint = pow(max(dot(normal, normalize(vec3f(-0.45, -0.55, 1.0))), 0.0), 48.0);
  color += vec3f(glint * wet * 0.1);

  // The page underneath is known, so solve for the least opaque pixel that
  // still lands on `color`. The sheet's own grain shows through the rest.
  let wanted = toSrgb(color);
  let page = toSrgb(params.paper);
  let change = abs(wanted - page);
  let alpha = clamp(max(max(change.r, change.g), change.b) * 4.0 + showCover, 0.0, 1.0);
  if (alpha <= 0.002) {
    return vec4f(0.0);
  }
  return vec4f(clamp(wanted - page * (1.0 - alpha), vec3f(0.0), vec3f(alpha)), alpha);
}
'''
