import { openEditor } from "./app.mjs";
async function run(label, { ink = true, economy = false } = {}) {
  const { b, p, logs } = await openEditor({ zen: true });
  if (!ink) await p.evaluate(() => { localStorage.setItem("twyne:ink:v1", "off"); window.dispatchEvent(new CustomEvent("twyne:ink-preference", { detail: false })); });
  await p.evaluate(async ({ economy }) => {
    window.__events = [];
    new PerformanceObserver((list) => { for (const e of list.getEntries()) if (["keydown", "keypress", "keyup", "beforeinput", "input"].includes(e.name)) window.__events.push(e.duration); }).observe({ type: "event", buffered: false, durationThreshold: 0 });
    const m = await import("/src/utils/ink/engine.ts");
    const engine = await m.inkEngine();
    if (engine) engine.measure = true;
    if (economy) window.__release = m.holdInkEconomy();
    window.__samples = [];
    window.__timer = setInterval(() => { if (engine && engine.stats.awake) window.__samples.push({ ...engine.stats }); }, 200);
    // rAF gaps while typing, the frame budget the writer feels
    window.__gaps = []; let last = 0;
    const loop = (t) => { if (last) window.__gaps.push(t - last); last = t; window.__raf = requestAnimationFrame(loop); };
    window.__raf = requestAnimationFrame(loop);
  }, { economy });
  const para = p.locator("#twyne-editor-mount .ProseMirror p").first();
  await para.click();
