/**
 * How a sheet of ink behaves. Every surface runs the same simulation; a
 * preset only changes how wet, how thirsty, and how long it stays.
 */
export interface InkTuning {
  /** CSS pixels per simulation cell. Smaller is finer and costs more. */
  cellPx: number;
  /** Capillary speed between cells. Above ~0.2 the step goes unstable. */
  flow: number;
  /** 0 spreads evenly, 1 runs only along the grain. */
  anisotropy: number;
  /** How fast suspended pigment settles into dense fibers. */
  absorb: number;
  /** Water lost per step. */
  evaporation: number;
  /** Extra drying at the wet edge, which pulls pigment out into a rim. */
  edgeRing: number;
  /** How fast a dried stain eases back into the page. */
  fade: number;
  /** Water below this is a pinned film that no longer travels. */
  pin: number;
  /** How much ink must pass before a cover is soaked through. */
  revealAt: number;
  /** Share of the moving water's pigment that keeps up with it. */
  carry: number;
  /** Pigment strength when composited. */
  strength: number;
  /** How much standing water darkens and glints. */
  sheen: number;
  /** How much the fiber sheet breaks up the stain. */
  grain: number;
  /** Simulation steps per animation frame. */
  substeps: number;
  /** A surface sleeps this long after its last drop. */
  lifetimeMs: number;
}

export type InkPreset = "typing" | "bleed" | "wick" | "stamp";

export const INK_PRESETS: Record<InkPreset, InkTuning> = {
  // A faint wet halo behind each new letter, dry in about half a second.
  typing: {
    cellPx: 3,
    flow: 0.13,
    anisotropy: 0.55,
    absorb: 0.012,
    evaporation: 0.012,
    edgeRing: 2.4,
    fade: 0.035,
    pin: 0.02,
    revealAt: 0.4,
    carry: 0.85,
    strength: 0.06,
    sheen: 1,
    grain: 0.5,
    substeps: 2,
    lifetimeMs: 1600,
  },
  // New words soaking up through the page.
  bleed: {
    cellPx: 2,
    flow: 0.15,
    anisotropy: 0.6,
    absorb: 0.02,
    evaporation: 0.006,
    edgeRing: 3,
    fade: 0.02,
    pin: 0.025,
    revealAt: 0.35,
    carry: 0.8,
    strength: 0.08,
    sheen: 1,
    grain: 0.4,
    substeps: 2,
    lifetimeMs: 2200,
  },
  // A strike line that wicks along its length.
  wick: {
    cellPx: 1,
    flow: 0.16,
    anisotropy: 0.85,
    absorb: 0.03,
    evaporation: 0.007,
    edgeRing: 2.2,
    fade: 0.012,
    pin: 0.02,
    revealAt: 0.4,
    carry: 0.9,
    strength: 2.6,
    sheen: 0.6,
    grain: 0.55,
    substeps: 2,
    lifetimeMs: 2600,
  },
  // Ink pooling at a stamp's edges, plus the spatter it throws.
  stamp: {
    cellPx: 1.5,
    flow: 0.12,
    anisotropy: 0.5,
    absorb: 0.025,
    evaporation: 0.005,
    edgeRing: 4,
    fade: 0.008,
    pin: 0.025,
    revealAt: 0.4,
    carry: 0.9,
    strength: 2.6,
    sheen: 0.8,
    grain: 0.6,
    substeps: 2,
    lifetimeMs: 3200,
  },
};

/** Sliders the lab exposes, with the range the step stays stable in. */
export const INK_TUNING_RANGES: Partial<
  Record<keyof InkTuning, { min: number; max: number; step: number }>
> = {
  flow: { min: 0.02, max: 0.2, step: 0.005 },
  anisotropy: { min: 0, max: 1, step: 0.05 },
  absorb: { min: 0, max: 0.08, step: 0.002 },
  evaporation: { min: 0.001, max: 0.03, step: 0.001 },
  edgeRing: { min: 0, max: 8, step: 0.1 },
  fade: { min: 0, max: 0.08, step: 0.002 },
  pin: { min: 0.005, max: 0.08, step: 0.005 },
  carry: { min: 0.2, max: 1, step: 0.05 },
  strength: { min: 0.01, max: 3, step: 0.01 },
  sheen: { min: 0, max: 1.5, step: 0.05 },
  grain: { min: 0, max: 0.9, step: 0.05 },
};

/**
 * Parses the colour a computed style returns: `rgb()`/`rgba()`, or the
 * `color(srgb …)` form Chromium uses once `color-mix()` is involved.
 */
export function parseComputedRgb(
  value: string,
): [number, number, number] | null {
  const srgb = value.match(
    /color\(srgb\s+([\d.]+)\s+([\d.]+)\s+([\d.]+)(?:\s*\/\s*([\d.]+%?))?\s*\)/,
  );
  if (srgb) {
    if (srgb[4] !== undefined && parseFloat(srgb[4]) === 0) return null;
    return [Number(srgb[1]), Number(srgb[2]), Number(srgb[3])];
  }
  const match = value.match(
    /rgba?\(\s*([\d.]+)[\s,]+([\d.]+)[\s,]+([\d.]+)(?:[\s,/]+([\d.]+%?))?\s*\)/,
  );
  if (!match) return null;
  const alpha = match[4];
  if (alpha !== undefined && parseFloat(alpha) === 0) return null;
  return [
    Number(match[1]) / 255,
    Number(match[2]) / 255,
    Number(match[3]) / 255,
  ];
}

export function srgbToLinear(c: number): number {
  return c <= 0.04045 ? c / 12.92 : ((c + 0.055) / 1.055) ** 2.4;
}

export function relativeLuminance([r, g, b]: [number, number, number]): number {
  return (
    0.2126 * srgbToLinear(r) +
    0.7152 * srgbToLinear(g) +
    0.0722 * srgbToLinear(b)
  );
}

import { component$, useSignal, useVisibleTask$ } from "@qwik.dev/core";
import { INK_PREFERENCE_KEY, setInkPreferred } from "../../utils/ink/engine";

/** The one switch for wet ink on this device. */
export const WetInkSetting = component$(() => {
  const on = useSignal(true);
  const reduced = useSignal(false);
  const supported = useSignal(true);
  // eslint-disable-next-line qwik/no-use-visible-task
  useVisibleTask$(() => {
    supported.value = "gpu" in navigator;
    reduced.value = window.matchMedia(
      "(prefers-reduced-motion: reduce)",
    ).matches;
    try {
      on.value = localStorage.getItem(INK_PREFERENCE_KEY) !== "off";
    } catch {
      on.value = true;
    }
  });
  const note = !supported.value
    ? "This browser has no WebGPU, so the page stays dry."
    : reduced.value
      ? "Off while your system asks for reduced motion."
      : "Letters soak into the page as you type; accepted edits ink in.";
  return (
    <label class="mt-4 flex cursor-pointer items-center justify-between border-t border-dashed border-[var(--color-paper-3)] pt-4">
      <div>
        <span
          class="block text-sm text-[var(--color-ink)]"
          style={{ fontFamily: "var(--font-display)" }}
        >
          Wet ink
        </span>
        <span
          class="text-[0.65rem] text-[var(--color-ink-muted)]"
          style={{ fontFamily: "var(--font-typewriter)" }}
        >
          {note}
        </span>
      </div>
      <input
        type="checkbox"
        checked={on.value}
        disabled={!supported.value}
        onChange$={(_, el) => {
          on.value = el.checked;
          setInkPreferred(el.checked);
        }}
        class="sr-only"
      />
      <span
        class={`relative inline-flex h-5 w-9 items-center rounded-full transition-colors ${
          on.value && supported.value
            ? "bg-[var(--color-vermilion)]"
            : "bg-[var(--color-paper-3)]"
        }`}
      >
        <span
          class={`inline-block h-3.5 w-3.5 transform rounded-full bg-[var(--color-paper)] transition-transform ${
            on.value && supported.value ? "translate-x-5" : "translate-x-1"
          }`}
        />
      </span>
    </label>
  );
});

// Composites the wet field onto the page. The canvas sits under real text,
// so it only ever paints paper, wetness, and pigment.

struct RenderParams {
  paper: vec3f,
  strength: f32,
  ink: vec3f,
  sheen: f32,
  cover: vec3f,
  revealing: f32,
  texel: vec2f,
  fiberScale: vec2f,
  fiberOffset: vec2f,
  dark: f32,
  grain: f32,
  // 0..1 past the point a cover must lift whether or not ink reached it.
  lift: f32,
}

@group(0) @binding(0) var field: texture_2d<f32>;
@group(0) @binding(1) var fieldSampler: sampler;
@group(0) @binding(2) var fibers: texture_2d<f32>;
@group(0) @binding(3) var fiberSampler: sampler;
@group(0) @binding(4) var<uniform> params: RenderParams;

struct VertexOut {
  @builtin(position) position: vec4f,
  @location(0) uv: vec2f,
}

@vertex
fn vs(@builtin(vertex_index) i: u32) -> VertexOut {
  let corner = vec2f(f32((i << 1u) & 2u), f32(i & 2u));
  var out: VertexOut;
  out.position = vec4f(corner * 2.0 - 1.0, 0.0, 1.0);
  out.uv = vec2f(corner.x, 1.0 - corner.y);
  return out;
}

// Pigment over paper. On a light sheet the ink absorbs (Kubelka–Munk), so
// layers deepen the way ink does rather than greying like alpha. Only
// opaque ink shows on a dark sheet, so there it covers like gouache.
// `amount` is normalised by the ink's own strongest absorption, so 1 is
// full-strength ink whatever its hue.
fn pigmentOver(base: vec3f, ink: vec3f, amount: f32) -> vec3f {
  if (params.dark > 0.5) {
    return mix(base, ink, 1.0 - exp(-amount * 2.5));
  }
  let inkKs = kmAbsorption(ink);
  let scale = 8.0 / max(max(inkKs.r, inkKs.g), max(inkKs.b, 1e-3));
  return kmReflectance(kmAbsorption(base) + inkKs * amount * scale);
}

// A soft field drawn with a hard edge: wet and dry paper meet at a sharp,
// ragged contact line, not a blur. `rag` roughens it along the fibers.
fn contact(value: f32, threshold: f32, rag: f32) -> f32 {
  let v = value + rag;
  let aa = max(fwidth(v), 1e-4) * 0.75;
  return smoothstep(threshold - aa, threshold + aa, v);
}

@fragment
fn fs(in: VertexOut) -> @location(0) vec4f {
  let s = textureSample(field, fieldSampler, in.uv);
  let fiber = textureSample(fibers, fiberSampler, in.uv * params.fiberScale + params.fiberOffset);
  let rag = (fiber.r - 0.5) * params.grain;
  let tooth = mix(1.0 - params.grain * 0.6, 1.0 + params.grain * 0.6, fiber.r);

  // Neighbouring water, for both the glint and the meniscus at the edge.
  let dx = textureSample(field, fieldSampler, in.uv + vec2f(params.texel.x, 0.0)).x
    - textureSample(field, fieldSampler, in.uv - vec2f(params.texel.x, 0.0)).x;
  let dy = textureSample(field, fieldSampler, in.uv + vec2f(0.0, params.texel.y)).x
    - textureSample(field, fieldSampler, in.uv - vec2f(0.0, params.texel.y)).x;

  let water = s.x;
  let pigment = s.y * 0.7 + s.z;
  let wet = contact(water, 0.05, rag * 0.08) * params.sheen;
  let stained = contact(pigment, 0.008, rag * 0.006);
  // Inside the stain the density follows the pigment, never dropping to a
  // wash so thin it reads as a tint rather than ink.
  let density = stained * (0.06 + pigment) * params.strength * tooth
    * select(1.0, 0.45, params.dark > 0.5);

  // Under the stain: the cover (while revealing) or the page itself.
  // The cover is a little thin, so the sheet's grain still shows through.
  let revealed = smoothstep(0.15, 0.85, s.w + rag * 0.4);
  let showCover = params.revealing * (1.0 - revealed) * (1.0 - params.lift) * 0.93;
  let ground = mix(params.paper, params.cover, showCover);

  // Wet paper loses the air between its fibers: deeper and a little richer
  // in its own colour, rather than greyer.
  let deepened = select(pow(ground, vec3f(1.7)) * 0.95, ground * 0.7, params.dark > 0.5);
  let soaked = mix(ground, deepened, wet);
  var color = pigmentOver(soaked, params.ink, density);

  // A thin glint off standing water, lit from the upper left.
  let normal = normalize(vec3f(-dx * 4.0, -dy * 4.0, 1.0));
  let glint = pow(max(dot(normal, normalize(vec3f(-0.45, -0.55, 1.0))), 0.0), 48.0);
  color += vec3f(glint * wet * 0.1);

  // The page underneath is known, so solve for the least opaque pixel that
  // still lands on `color`. The sheet's own grain shows through the rest.
  let wanted = toSrgb(color);
  let page = toSrgb(params.paper);
  let change = abs(wanted - page);
  let alpha = clamp(max(max(change.r, change.g), change.b) * 4.0 + showCover, 0.0, 1.0);
  if (alpha <= 0.002) {
    return vec4f(0.0);
  }
  return vec4f(clamp(wanted - page * (1.0 - alpha), vec3f(0.0), vec3f(alpha)), alpha);
}

