2	 * How a sheet of ink behaves. Every surface runs the same simulation; a
3	 * preset only changes how wet, how thirsty, and how long it stays.
4	 */
5	export interface InkTuning {
6	  /** CSS pixels per simulation cell. Smaller is finer and costs more. */
7	  cellPx: number;
8	  /** Capillary speed between cells. Above ~0.2 the step goes unstable. */
9	  flow: number;
10	  /** 0 spreads evenly, 1 runs only along the grain. */
11	  anisotropy: number;
12	  /** How fast suspended pigment settles into dense fibers. */
13	  absorb: number;
14	  /** Water lost per step. */
15	  evaporation: number;
16	  /** Extra drying at the wet edge, which pulls pigment out into a rim. */
17	  edgeRing: number;
18	  /** How fast a dried stain eases back into the page. */
19	  fade: number;
20	  /** Water below this is a pinned film that no longer travels. */
21	  pin: number;
22	  /** How much ink must pass before a cover is soaked through. */
23	  revealAt: number;
24	  /** Share of the moving water's pigment that keeps up with it. */
25	  carry: number;
26	  /** Pigment strength when composited. */
27	  strength: number;
28	  /** How much standing water darkens and glints. */
29	  sheen: number;
30	  /** How much the fiber sheet breaks up the stain. */
31	  grain: number;
32	  /** Simulation steps per animation frame. */
33	  substeps: number;
34	  /** A surface sleeps this long after its last drop. */
35	  lifetimeMs: number;
36	}
