132	/**
133	 * Parses the colour a computed style returns: `rgb()`/`rgba()`, or the
134	 * `color(srgb …)` form Chromium uses once `color-mix()` is involved.
135	 */
136	export function parseComputedRgb(
137	  value: string,
138	): [number, number, number] | null {
139	  const srgb = value.match(
140	    /color\(srgb\s+([\d.]+)\s+([\d.]+)\s+([\d.]+)(?:\s*\/\s*([\d.]+%?))?\s*\)/,
141	  );
142	  if (srgb) {
143	    if (srgb[4] !== undefined && parseFloat(srgb[4]) === 0) return null;
144	    return [Number(srgb[1]), Number(srgb[2]), Number(srgb[3])];
145	  }
146	  const match = value.match(
147	    /rgba?\(\s*([\d.]+)[\s,]+([\d.]+)[\s,]+([\d.]+)(?:[\s,/]+([\d.]+%?))?\s*\)/,
148	  );
149	  if (!match) return null;
150	  const alpha = match[4];
151	  if (alpha !== undefined && parseFloat(alpha) === 0) return null;
152	  return [
153	    Number(match[1]) / 255,
154	    Number(match[2]) / 255,
155	    Number(match[3]) / 255,
156	  ];
157	}
158	
159	export function srgbToLinear(c: number): number {
160	  return c <= 0.04045 ? c / 12.92 : ((c + 0.055) / 1.055) ** 2.4;
161	}
162	
163	export function relativeLuminance([r, g, b]: [number, number, number]): number {
164	  return (
165	    0.2126 * srgbToLinear(r) +
166	    0.7152 * srgbToLinear(g) +
167	    0.0722 * srgbToLinear(b)
168	  );
169	}
