1	// Composites the wet field onto the page. The canvas sits under real text,
2	// so it only ever paints paper, wetness, and pigment.
3	
4	struct RenderParams {
5	  paper: vec3f,
6	  strength: f32,
7	  ink: vec3f,
8	  sheen: f32,
9	  cover: vec3f,
10	  revealing: f32,
11	  texel: vec2f,
12	  fiberScale: vec2f,
13	  fiberOffset: vec2f,
14	  dark: f32,
15	  grain: f32,
16	  // 0..1 past the point a cover must lift whether or not ink reached it.
17	  lift: f32,
18	}
19	
20	@group(0) @binding(0) var field: texture_2d<f32>;
21	@group(0) @binding(1) var fieldSampler: sampler;
22	@group(0) @binding(2) var fibers: texture_2d<f32>;
23	@group(0) @binding(3) var fiberSampler: sampler;
24	@group(0) @binding(4) var<uniform> params: RenderParams;
25	
26	struct VertexOut {
27	  @builtin(position) position: vec4f,
28	  @location(0) uv: vec2f,
29	}
30	
31	@vertex
32	fn vs(@builtin(vertex_index) i: u32) -> VertexOut {
33	  let corner = vec2f(f32((i << 1u) & 2u), f32(i & 2u));
34	  var out: VertexOut;
35	  out.position = vec4f(corner * 2.0 - 1.0, 0.0, 1.0);
36	  out.uv = vec2f(corner.x, 1.0 - corner.y);
37	  return out;
38	}
39	
40	// Pigment over paper. On a light sheet the ink absorbs (Kubelka–Munk), so
41	// layers deepen the way ink does rather than greying like alpha. Only
42	// opaque ink shows on a dark sheet, so there it covers like gouache.
43	// `amount` is normalised by the ink's own strongest absorption, so 1 is
44	// full-strength ink whatever its hue.
45	fn pigmentOver(base: vec3f, ink: vec3f, amount: f32) -> vec3f {
46	  if (params.dark > 0.5) {
47	    return mix(base, ink, 1.0 - exp(-amount * 2.5));
48	  }
49	  let inkKs = kmAbsorption(ink);
50	  let scale = 8.0 / max(max(inkKs.r, inkKs.g), max(inkKs.b, 1e-3));
51	  return kmReflectance(kmAbsorption(base) + inkKs * amount * scale);
52	}
53	
54	// A soft field drawn with a hard edge: wet and dry paper meet at a sharp,
55	// ragged contact line, not a blur. `rag` roughens it along the fibers.
56	fn contact(value: f32, threshold: f32, rag: f32) -> f32 {
57	  let v = value + rag;
58	  let aa = max(fwidth(v), 1e-4) * 0.75;
59	  return smoothstep(threshold - aa, threshold + aa, v);
60	}
61	
62	@fragment
63	fn fs(in: VertexOut) -> @location(0) vec4f {
64	  let s = textureSample(field, fieldSampler, in.uv);
65	  let fiber = textureSample(fibers, fiberSampler, in.uv * params.fiberScale + params.fiberOffset);
66	  let rag = (fiber.r - 0.5) * params.grain;
67	  let tooth = mix(1.0 - params.grain * 0.6, 1.0 + params.grain * 0.6, fiber.r);
68	
69	  // Neighbouring water, for both the glint and the meniscus at the edge.
70	  let dx = textureSample(field, fieldSampler, in.uv + vec2f(params.texel.x, 0.0)).x
71	    - textureSample(field, fieldSampler, in.uv - vec2f(params.texel.x, 0.0)).x;
72	  let dy = textureSample(field, fieldSampler, in.uv + vec2f(0.0, params.texel.y)).x
73	    - textureSample(field, fieldSampler, in.uv - vec2f(0.0, params.texel.y)).x;
74	
75	  let water = s.x;
76	  let pigment = s.y * 0.7 + s.z;
77	  let wet = contact(water, 0.05, rag * 0.08) * params.sheen;
78	  let stained = contact(pigment, 0.008, rag * 0.006);
79	  // Inside the stain the density follows the pigment, never dropping to a
80	  // wash so thin it reads as a tint rather than ink.
81	  let density = stained * (0.06 + pigment) * params.strength * tooth
82	    * select(1.0, 0.45, params.dark > 0.5);
83	
84	  // Under the stain: the cover (while revealing) or the page itself.
85	  // The cover is a little thin, so the sheet's grain still shows through.
86	  let revealed = smoothstep(0.15, 0.85, s.w + rag * 0.4);
87	  let showCover = params.revealing * (1.0 - revealed) * (1.0 - params.lift) * 0.93;
88	  let ground = mix(params.paper, params.cover, showCover);
89	
90	  // Wet paper loses the air between its fibers: deeper and a little richer
91	  // in its own colour, rather than greyer.
92	  let deepened = select(pow(ground, vec3f(1.7)) * 0.95, ground * 0.7, params.dark > 0.5);
93	  let soaked = mix(ground, deepened, wet);
94	  var color = pigmentOver(soaked, params.ink, density);
95	
96	  // A thin glint off standing water, lit from the upper left.
97	  let normal = normalize(vec3f(-dx * 4.0, -dy * 4.0, 1.0));
98	  let glint = pow(max(dot(normal, normalize(vec3f(-0.45, -0.55, 1.0))), 0.0), 48.0);
99	  color += vec3f(glint * wet * 0.1);
100	
101	  // The page underneath is known, so solve for the least opaque pixel that
102	  // still lands on `color`. The sheet's own grain shows through the rest.
103	  let wanted = toSrgb(color);
104	  let page = toSrgb(params.paper);
105	  let change = abs(wanted - page);
106	  let alpha = clamp(max(max(change.r, change.g), change.b) * 4.0 + showCover, 0.0, 1.0);
107	  if (alpha <= 0.002) {
108	    return vec4f(0.0);
109	  }
110	  return vec4f(clamp(wanted - page * (1.0 - alpha), vec3f(0.0), vec3f(alpha)), alpha);
111	}
