/* The same physical die prints workflow acknowledgements and verdicts.
   Only the brief press moves; the final ink stays put and remains readable. */
.ink-stamp {
  position: relative;
  display: block;
  width: 100%;
  height: 100%;
  isolation: isolate;
  pointer-events: none;
}
.ink-stamp__imprint {
  position: absolute;
  inset: 0;
  display: block;
  opacity: 0.88;
}
.ink-stamp__tool {
  position: absolute;
  z-index: 3;
  top: -70%;
  left: -32.5%;
  display: block;
  width: 165%;
  max-width: none;
  height: auto;
  opacity: 0;
  object-fit: contain;
  transform-origin: 50% 82%;
  user-select: none;
}
.ink-stamp__contact-shadow {
  position: absolute;
  z-index: 2;
  inset: 26% 16% 18%;
  border-radius: 50%;
  background: #20150c;
  filter: blur(5px);
  opacity: 0;
}
.ink-stamp--pressing .ink-stamp__tool {
  animation: stamp-die-press 500ms linear both;
}
.ink-stamp--pressing .ink-stamp__imprint {
  animation: stamp-ink-settle 500ms linear both;
}
.ink-stamp--pressing .ink-stamp__contact-shadow {
  animation: stamp-contact-shadow 500ms linear both;
}

.rubric-grade-stamp {
  --stamp-rotation: -4deg;
  position: relative;
  display: grid;
  flex: 0 0 auto;
  place-items: center;
  color: var(--color-ink);
  transform: rotate(var(--stamp-rotation));
  transform-origin: center;
  isolation: isolate;
}
.rubric-grade-stamp__mark {
  position: absolute;
  inset: 0;
  background: currentColor;
  -webkit-mask: var(--rubric-stamp-image) center / contain no-repeat;
  mask: var(--rubric-stamp-image) center / contain no-repeat;
}
.rubric-grade-stamp--compact {
  width: 5.5rem;
  height: 5.5rem;
}
.rubric-grade-stamp--report {
  width: 9rem;
  height: 9rem;
}
.rubric-grade-stamp--a {
  --stamp-rotation: -5deg;
}
.rubric-grade-stamp--b {
  --stamp-rotation: 3deg;
}
.rubric-grade-stamp--c {
  --stamp-rotation: -2deg;
}
.rubric-grade-stamp--revise {
  --stamp-rotation: 4deg;
}
.rubric-grade-stamp--animated {
  z-index: 2;
}
/* Give the handle room above the compact mark, without affecting layout. */
.rubric-proof:has(.rubric-grade-stamp--animated) {
  overflow: visible;
}

.workflow-stamp {
  position: relative;
  display: block;
  width: min(15rem, 65vw);
  aspect-ratio: 1;
  color: var(--color-vermilion);
  transform: rotate(-4deg);
  flex: 0 0 auto;
  pointer-events: none;
}
.workflow-stamp__mark {
  position: absolute;
  inset: 0;
  background: currentColor;
  -webkit-mask: var(--workflow-stamp-image) center / contain no-repeat;
  mask: var(--workflow-stamp-image) center / contain no-repeat;
}
.dossier-filed-confirmation__paper:has(.workflow-stamp) {
  border: 0;
  box-shadow: none;
  background: transparent;
  padding: 0;
  text-transform: none;
  animation: none;
}
.dossier-filed-confirmation__paper .workflow-stamp {
  margin-block: -2rem;
}

@keyframes rubric-proof-settle {
  from {
    filter: contrast(0.96) brightness(1.025);
    transform: translateY(-4px) scaleY(0.992);
  }
  to {
    filter: contrast(1) brightness(1);
    transform: translateY(0) scaleY(1);
  }
}

/* Approach, contact at 160ms, a brief compression, then a clean lift. */
@keyframes stamp-die-press {
  0% {
    opacity: 0;
    transform: translate(14%, -48%) rotate(-10deg) scale(1.12);
    animation-timing-function: cubic-bezier(0.55, 0, 0.85, 0.55);
  }
  14% {
    opacity: 1;
    transform: translate(8%, -27%) rotate(-5deg) scale(1.07);
    animation-timing-function: cubic-bezier(0.55, 0, 0.85, 0.55);
  }
  32% {
    opacity: 1;
    transform: translate(0, 0) rotate(0) scale(1);
  }
  41% {
    transform: translate(0, 1%) rotate(0) scale(1.015, 0.975);
  }
  52% {
    transform: translate(0, 0) rotate(0) scale(1);
    animation-timing-function: cubic-bezier(0.22, 1, 0.36, 1);
  }
  76% {
    opacity: 1;
    transform: translate(4%, -19%) rotate(3deg) scale(1.025);
  }
  100% {
    opacity: 0;
    transform: translate(14%, -48%) rotate(8deg) scale(1.07);
  }
}
@keyframes stamp-ink-settle {
  0%,
  31% {
    opacity: 0;
    transform: scale(0.988);
  }
  32% {
    opacity: 1;
    transform: scale(0.988);
    filter: blur(0.35px);
  }
  54% {
    opacity: 0.98;
    transform: scale(1.004);
    filter: blur(0.15px);
  }
  100% {
    opacity: 0.88;
    transform: scale(1);
    filter: blur(0);
  }
}
@keyframes stamp-contact-shadow {
  0% {
    opacity: 0;
    transform: translate(8%, 4%) scale(1.3);
  }
  20% {
    opacity: 0.12;
    transform: translate(3%, 2%) scale(1.12);
  }
  32%,
  52% {
    opacity: 0.24;
    transform: translate(0, 0) scale(1);
  }
  100% {
    opacity: 0;
    transform: translate(8%, 4%) scale(1.3);
  }
}
@media (prefers-reduced-motion: reduce) {
  .ink-stamp__tool,
  .ink-stamp__contact-shadow {
    display: none;
  }
  .ink-stamp--pressing .ink-stamp__imprint,
  .rubric-proof--fresh {
    animation: none;
  }
}

/* Rubric score animation — fills from 0 to the inline width */
@keyframes rubric-fill {
  from {
    width: 0;
  position: absolute;
  z-index: 5;
  pointer-events: none;
}
.ink-moment--under {
  z-index: auto;
}

/* The proof comes back with nothing left to answer. */
.clean-proof-overlay > div {
  animation: stamp-acknowledgement-fade 260ms ease-out 2300ms forwards;
}
@media (prefers-reduced-motion: reduce) {
  .clean-proof-overlay > div {
    animation: none;
  }
}
.clean-proof-stamp {
  --stamp-rotation: -7deg;
  position: relative;
  display: block;
  width: 9.5rem;
  aspect-ratio: 1;
  color: var(--color-vermilion);
  transform: rotate(var(--stamp-rotation));
  pointer-events: none;
}
.clean-proof-stamp__mark {
  position: absolute;
  inset: 0;
  display: grid;
  place-content: center;
  gap: 0.1rem;
  border: 3px solid currentColor;
  border-radius: 50%;
  outline: 1px solid currentColor;
  outline-offset: -9px;
  font-family: var(--font-typewriter);
  text-align: center;
  text-transform: uppercase;
  letter-spacing: 0.14em;
  line-height: 1.05;
}
.clean-proof-stamp__mark b {
  font-family: var(--font-display);
  font-size: 1.3rem;
  letter-spacing: 0.06em;
}
.clean-proof-stamp__mark small {
  font-size: 0.6rem;
}
