1	/**
2	 * Wet ink on WebGPU. One device, one set of WGSL pipelines and one fiber
3	 * sheet are shared; every place ink appears gets its own canvas surface
4	 * with its own field. All awake surfaces step and present in a single
5	 * submission per frame, and a surface with nothing wet on it costs nothing.
6	 *
7	 * The simulation never touches the text it sits under or over, so input,
8	 * selection and screen readers are unaffected by anything here.
9	 */
10	import commonWgsl from "./wgsl/common.wgsl?raw";
11	import fibersWgsl from "./wgsl/fibers.wgsl?raw";
12	import renderWgsl from "./wgsl/render.wgsl?raw";
13	import simWgsl from "./wgsl/sim.wgsl?raw";
14	import splatterWgsl from "./wgsl/splatter.wgsl?raw";
15	import {
16	  INK_PRESETS,
17	  parseComputedRgb,
18	  relativeLuminance,
19	  srgbToLinear,
20	  type InkPreset,
21	  type InkTuning,
22	} from "./tuning";
23	
24	const FIBER_SIZE = 512;
25	const MAX_DROPS = 64;
26	const MAX_DROPLETS = 512;
27	const DROP_FLOATS = 8;
28	const DROPLET_FLOATS = 8;
29	const MASS_UNITS = 1024;
30	const MAX_DPR = 2;
31	/** A 0..1 value as an IEEE half float, for writing rgba16float fields. */
32	function toHalf(v: number): number {
33	  if (v <= 0) return 0;
34	  if (v >= 1) return 0x3c00;
35	  const exponent = Math.floor(Math.log2(v));
36	  if (exponent < -14) return Math.round(v * 2 ** 24);
37	  const mantissa = Math.round((v / 2 ** exponent - 1) * 1024);
38	  return ((exponent + 15) << 10) + mantissa;
39	}
40	
41	export const INK_PREFERENCE_KEY = "twyne:ink:v1";
42	
43	type Rgb = [number, number, number];
44	
45	/** On unless the writer switched it off or asked for reduced motion. */
46	export function inkPreferred(): boolean {
47	  if (typeof window === "undefined") return false;
48	  if (window.matchMedia?.("(prefers-reduced-motion: reduce)").matches) {
49	    return false;
50	  }
51	  try {
52	    return window.localStorage.getItem(INK_PREFERENCE_KEY) !== "off";
53	  } catch {
54	    return true;
55	  }
56	}
57	
58	export function setInkPreferred(on: boolean): void {
59	  try {
60	    if (on) window.localStorage.removeItem(INK_PREFERENCE_KEY);
61	    else window.localStorage.setItem(INK_PREFERENCE_KEY, "off");
62	  } catch {
63	    // Private browsing: the choice lasts for this page only.
64	  }
65	  window.dispatchEvent(new CustomEvent("twyne:ink-preference", { detail: on }));
66	}
67	
68	let economyHolds = 0;
69	
70	/**
71	 * Local Live voice runs its model on the same GPU. While it holds this,
72	 * ink takes one simulation step per frame instead of its usual count.
73	 */
74	export function holdInkEconomy(): () => void {
75	  economyHolds++;
76	  let released = false;
77	  return () => {
78	    if (released) return;
79	    released = true;
80	    economyHolds = Math.max(0, economyHolds - 1);
81	  };
82	}
83	
84	export interface InkStats {
85	  adapter: string;
86	  fps: number;
87	  /** Encoding and submitting one frame on the main thread. */
88	  cpuMs: number;
89	  /** GPU time for one frame, when the adapter exposes timestamps. */
90	  gpuMs: number | null;
91	  awake: number;
92	  economy: boolean;
93	}
94	
95	export interface InkDrop {
96	  /** CSS pixels from the surface's top-left. */
97	  x: number;
98	  y: number;
99	  /** Lay the drop along a segment instead of a point. */
100	  toX?: number;
101	  toY?: number;
102	  radius: number;
103	  water: number;
104	  pigment: number;
105	  /** How much the fibers break up the drop's edge. */
106	  ragged?: number;
107	}
108	
109	export interface InkSplatter {
110	  x: number;
111	  y: number;
112	  count: number;
113	  /** CSS pixels per frame at launch. */
114	  speed: number;
115	  /** Radians of the arc thrown; a full circle by default. */
116	  arc?: number;
117	  heading?: number;
118	  mass?: number;
119	}
120	
121	export interface InkColors {
122	  /** sRGB 0..1. The page the canvas composites onto. */
123	  paper: Rgb;
124	  ink: Rgb;
125	  /** What hides content until ink soaks through it. Defaults to paper. */
126	  cover?: Rgb;
127	}
128	
129	let enginePromise: Promise<InkEngine | null> | null = null;
130	
131	/** The shared engine, or null where WebGPU is missing or ink is off. */
132	export function inkEngine(): Promise<InkEngine | null> {
133	  if (typeof navigator === "undefined" || !("gpu" in navigator)) {
134	    return Promise.resolve(null);
135	  }
136	  if (!inkPreferred()) return Promise.resolve(null);
137	  enginePromise ??= InkEngine.create().catch((err) => {
138	    console.warn("[twyne:ink] WebGPU unavailable", err);
139	    enginePromise = null;
140	    return null;
141	  });
142	  return enginePromise;
143	}
144	
145	async function checkedModule(
146	  device: GPUDevice,
147	  label: string,
148	  source: string,
149	): Promise<GPUShaderModule> {
150	  const module = device.createShaderModule({
151	    label,
152	    code: `${commonWgsl}\n${source}`,
153	  });
154	  const info = await module.getCompilationInfo();
155	  const errors = info.messages.filter((m) => m.type === "error");
156	  if (errors.length) {
157	    throw new Error(
158	      `${label}: ${errors.map((m) => `${m.lineNum}:${m.linePos} ${m.message}`).join("; ")}`,
159	    );
160	  }
161	  return module;
162	}
163	
164	interface Timestamps {
165	  set: GPUQuerySet;
166	  resolve: GPUBuffer;
167	  read: GPUBuffer;
168	  pending: boolean;
169	}
170	
171	export class InkEngine {
172	  private readonly awake = new Set<InkSurface>();
173	  private readonly surfaces = new Set<InkSurface>();
174	  private frame = 0;
175	  private lastTick = 0;
176	  private dead = false;
177	  private timestamps: Timestamps | null = null;
178	  /** Collect GPU timings; the lab turns this on. */
179	  measure = false;
180	  private quiet = false;
181	  readonly stats: InkStats;
182	
183	  private constructor(
184	    readonly device: GPUDevice,
185	    readonly format: GPUTextureFormat,
186	    readonly fibers: GPUTexture,
187	    readonly simPipeline: GPUComputePipeline,
188	    readonly splatterPipeline: GPUComputePipeline,
189	    readonly renderPipeline: GPURenderPipeline,
190	    readonly fieldSampler: GPUSampler,
191	    readonly fiberSampler: GPUSampler,
192	    adapter: string,
193	  ) {
194	    this.stats = {
195	      adapter,
196	      fps: 0,
197	      cpuMs: 0,
198	      gpuMs: null,
199	      awake: 0,
200	      economy: false,
201	    };
202	    if (device.features.has("timestamp-query")) {
203	      this.timestamps = {
204	        set: device.createQuerySet({ type: "timestamp", count: 2 }),
205	        resolve: device.createBuffer({
206	          size: 16,
207	          usage: GPUBufferUsage.QUERY_RESOLVE | GPUBufferUsage.COPY_SRC,
208	        }),
209	        read: device.createBuffer({
210	          size: 16,
211	          usage: GPUBufferUsage.MAP_READ | GPUBufferUsage.COPY_DST,
212	        }),
213	        pending: false,
214	      };
215	    }
216	    void device.lost.then((info) => {
217	      this.dead = true;
218	      enginePromise = null;
219	      if (info.reason !== "destroyed") {
220	        console.warn("[twyne:ink] device lost", info.message);
221	      }
222	      for (const surface of this.surfaces) surface.markLost();
223	    });
224	  }
