226	  static async create(): Promise<InkEngine | null> {
227	    const adapter = await navigator.gpu.requestAdapter({
228	      powerPreference: "low-power",
229	    });
230	    if (!adapter) return null;
231	    const features: GPUFeatureName[] = adapter.features.has("timestamp-query")
232	      ? ["timestamp-query"]
233	      : [];
234	    const device = await adapter.requestDevice({
235	      label: "twyne ink",
236	      requiredFeatures: features,
237	    });
238	    const format = navigator.gpu.getPreferredCanvasFormat();
239	    const [fiberModule, simModule, splatterModule, renderModule] =
240	      await Promise.all([
241	        checkedModule(device, "ink fibers", fibersWgsl),
242	        checkedModule(device, "ink sim", simWgsl),
243	        checkedModule(device, "ink splatter", splatterWgsl),
244	        checkedModule(device, "ink render", renderWgsl),
245	      ]);
246	    const [fiberPipeline, simPipeline, splatterPipeline, renderPipeline] =
247	      await Promise.all([
248	        device.createComputePipelineAsync({
249	          label: "ink fibers",
250	          layout: "auto",
251	          compute: { module: fiberModule, entryPoint: "main" },
252	        }),
253	        device.createComputePipelineAsync({
254	          label: "ink sim",
255	          layout: "auto",
256	          compute: { module: simModule, entryPoint: "main" },
257	        }),
258	        device.createComputePipelineAsync({
259	          label: "ink splatter",
260	          layout: "auto",
261	          compute: { module: splatterModule, entryPoint: "main" },
262	        }),
263	        device.createRenderPipelineAsync({
264	          label: "ink render",
265	          layout: "auto",
266	          vertex: { module: renderModule, entryPoint: "vs" },
267	          fragment: {
268	            module: renderModule,
269	            entryPoint: "fs",
270	            targets: [{ format }],
271	          },
272	          primitive: { topology: "triangle-list" },
273	        }),
274	      ]);
275	
276	    const fibers = device.createTexture({
277	      label: "ink fiber sheet",
278	      size: [FIBER_SIZE, FIBER_SIZE],
279	      format: "rgba8unorm",
280	      usage: GPUTextureUsage.STORAGE_BINDING | GPUTextureUsage.TEXTURE_BINDING,
281	    });
282	    const fiberParams = device.createBuffer({
283	      size: 16,
284	      usage: GPUBufferUsage.UNIFORM | GPUBufferUsage.COPY_DST,
285	    });
286	    const raw = new ArrayBuffer(16);
287	    new Uint32Array(raw, 0, 1)[0] = FIBER_SIZE;
288	    // Strand cell, grain angle (nearly level, as a sheet comes off the
289	    // wire), and how far strands stray from it.
290	    new Float32Array(raw, 4, 3).set([16, -0.06, 1.1]);
291	    device.queue.writeBuffer(fiberParams, 0, raw);
292	    const encoder = device.createCommandEncoder({ label: "ink fibers" });
293	    const pass = encoder.beginComputePass();
294	    pass.setPipeline(fiberPipeline);
295	    pass.setBindGroup(
296	      0,
297	      device.createBindGroup({
298	        layout: fiberPipeline.getBindGroupLayout(0),
299	        entries: [
300	          { binding: 0, resource: fibers.createView() },
301	          { binding: 1, resource: { buffer: fiberParams } },
302	        ],
303	      }),
304	    );
305	    pass.dispatchWorkgroups(FIBER_SIZE / 8, FIBER_SIZE / 8);
306	    pass.end();
307	    device.queue.submit([encoder.finish()]);
308	    fiberParams.destroy();
309	
310	    const info = adapter.info;
311	    return new InkEngine(
312	      device,
313	      format,
314	      fibers,
315	      simPipeline,
316	      splatterPipeline,
317	      renderPipeline,
318	      device.createSampler({ magFilter: "linear", minFilter: "linear" }),
319	      device.createSampler({
320	        magFilter: "linear",
321	        minFilter: "linear",
322	        addressModeU: "repeat",
323	        addressModeV: "repeat",
324	      }),
325	      [info.vendor, info.architecture].filter(Boolean).join(" ") || "webgpu",
326	    );
327	  }
