347	  /**
348	   * Hold the canvases still for the coming frame. A canvas presented in the
349	   * same frame as a typed letter delays that letter's paint by a frame, so
350	   * the letter goes first and the ink catches up on the next.
351	   */
352	  yieldFrame(): void {
353	    this.quiet = true;
354	  }
355	
356	  /** @internal */
357	  forget(surface: InkSurface): void {
358	    this.surfaces.delete(surface);
359	    this.awake.delete(surface);
360	  }
361	
362	  /** @internal */
363	  wake(surface: InkSurface): void {
364	    if (this.dead) return;
365	    const wasIdle = this.awake.size === 0;
366	    this.awake.add(surface);
367	    if (wasIdle) {
368	      this.lastTick = 0;
369	      requestAnimationFrame(this.tick);
370	    }
371	  }
372	
373	  private readonly tick = (now: number): void => {
374	    if (this.dead || this.awake.size === 0) return;
375	    const started = performance.now();
376	    const economy = economyHolds > 0;
377	    const present = !this.quiet;
378	    this.quiet = false;
379	    const timed =
380	      present &&
381	      this.measure &&
382	      this.timestamps !== null &&
383	      !this.timestamps.pending;
384	    const encoder = this.device.createCommandEncoder({ label: "ink frame" });
385	    const compute = encoder.beginComputePass(
386	      timed
387	        ? {
388	            timestampWrites: {
389	              querySet: this.timestamps!.set,
390	              beginningOfPassWriteIndex: 0,
391	            },
392	          }
393	        : undefined,
394	    );
395	    const surfaces = [...this.awake];
396	    for (const surface of surfaces) surface.step(compute, now, economy);
397	    compute.end();
398	    if (present)
399	      surfaces.forEach((surface, i) =>
400	        surface.render(
401	          encoder,
402	          now,
403	          timed && i === surfaces.length - 1 ? this.timestamps!.set : null,
404	        ),
405	      );
406	    if (timed) {
407	      const t = this.timestamps!;
408	      encoder.resolveQuerySet(t.set, 0, 2, t.resolve, 0);
409	      encoder.copyBufferToBuffer(t.resolve, 0, t.read, 0, 16);
410	    }
411	    this.device.queue.submit([encoder.finish()]);
412	    if (timed) this.readTimestamps();
413	
414	    // A surface's last frame clears its canvas, so it only sleeps on a
415	    // frame that presented.
416	    for (const surface of present ? surfaces : []) {
417	      if (!surface.asleep(now)) continue;
418	      this.awake.delete(surface);
419	      surface.onSleep?.();
420	    }
421	    const cpu = performance.now() - started;
422	    const interval = this.lastTick ? now - this.lastTick : 0;
423	    this.lastTick = now;
424	    this.frame++;
425	    this.stats.cpuMs = ema(this.stats.cpuMs, cpu, this.frame);
426	    if (interval > 0) {
427	      this.stats.fps = ema(this.stats.fps, 1000 / interval, this.frame);
428	    }
429	    this.stats.awake = this.awake.size;
430	    this.stats.economy = economy;
431	    if (this.awake.size) requestAnimationFrame(this.tick);
432	  };
433	
434	  private readTimestamps(): void {
435	    const t = this.timestamps!;
436	    t.pending = true;
437	    void t.read
438	      .mapAsync(GPUMapMode.READ)
439	      .then(() => {
440	        const [begin, end] = new BigUint64Array(t.read.getMappedRange());
441	        if (end > begin) {
442	          const ms = Number(end - begin) / 1e6;
443	          this.stats.gpuMs = ema(this.stats.gpuMs ?? ms, ms, this.frame);
444	        }
445	        t.read.unmap();
446	      })
447	      .catch(() => {})
448	      .finally(() => {
449	        t.pending = false;
450	      });
451	  }
452	}
453	
454	function ema(previous: number, next: number, frame: number): number {
455	  const k = frame < 10 ? 0.5 : 0.08;
456	  return previous + (next - previous) * k;
457	}
