504	  constructor(
505	    private readonly engine: InkEngine,
506	    readonly canvas: HTMLCanvasElement,
507	    public tuning: InkTuning,
508	  ) {
509	    const device = engine.device;
510	    const context = canvas.getContext("webgpu");
511	    if (!context) throw new Error("Canvas has no WebGPU context");
512	    context.configure({
513	      device,
514	      format: engine.format,
515	      alphaMode: "premultiplied",
516	    });
517	    this.context = context;
518	    const uniform = GPUBufferUsage.UNIFORM | GPUBufferUsage.COPY_DST;
519	    this.simParams = device.createBuffer({ size: 64, usage: uniform });
520	    this.quietParams = device.createBuffer({ size: 64, usage: uniform });
521	    this.renderParams = device.createBuffer({ size: 96, usage: uniform });
522	    this.splatterParams = device.createBuffer({ size: 32, usage: uniform });
523	    this.dropBuffer = device.createBuffer({
524	      size: MAX_DROPS * DROP_FLOATS * 4,
525	      usage: GPUBufferUsage.STORAGE | GPUBufferUsage.COPY_DST,
526	    });
527	    this.droplets = device.createBuffer({
528	      size: MAX_DROPLETS * DROPLET_FLOATS * 4,
529	      usage: GPUBufferUsage.STORAGE | GPUBufferUsage.COPY_DST,
530	    });
