545	  /** Match the canvas to its box. Clears anything still wet. */
546	  resize(cssWidth: number, cssHeight: number): void {
547	    if (this.dead) return;
548	    const width = Math.max(1, Math.round(cssWidth));
549	    const height = Math.max(1, Math.round(cssHeight));
550	    const dpr = Math.min(window.devicePixelRatio || 1, MAX_DPR);
551	    this.canvas.width = Math.max(1, Math.round(width * dpr));
552	    this.canvas.height = Math.max(1, Math.round(height * dpr));
553	    const cols = Math.ceil(width / this.tuning.cellPx);
554	    const rows = Math.ceil(height / this.tuning.cellPx);
555	    this.cssWidth = width;
556	    this.cssHeight = height;
557	    if (cols === this.cols && rows === this.rows && this.fields) return;
558	    this.cols = cols;
559	    this.rows = rows;
560	    this.allocate();
561	  }
562	
563	  setColors(colors: InkColors): void {
564	    this.paper = colors.paper;
565	    this.ink = colors.ink;
566	    this.cover = colors.cover ?? colors.paper;
567	    this.dark = relativeLuminance(colors.paper) < 0.3;
