569	
570	  /** Read the page and ink colours from CSS, resolved against `el`. */
571	  readColors(el: Element, ink: string, cover?: string): void {
572	    const paper = backgroundBehind(el);
573	    this.setColors({
574	      paper,
575	      ink: resolveCssColor(el, ink) ?? this.ink,
