579	
580	  drop(drop: InkDrop, delayMs = 0): void {
581	    if (this.dead || !this.fields) return;
582	    if (delayMs > 0) {
583	      this.scheduled.push({ at: performance.now() + delayMs, drop });
584	    } else {
585	      this.pending.push(drop);
586	    }
587	    this.touch();
