589	
590	  /** A line of ink drawn from one point to another over `durationMs`. */
591	  stroke(
592	    from: { x: number; y: number },
593	    to: { x: number; y: number },
594	    durationMs: number,
595	    ink: Omit<InkDrop, "x" | "y" | "toX" | "toY">,
596	    delayMs = 0,
597	  ): void {
598	    const steps = Math.max(1, Math.round(durationMs / 16));
599	    for (let i = 0; i < steps; i++) {
600	      const a = i / steps;
601	      const b = (i + 1) / steps;
602	      // The pen loads at the start and runs drier toward the end.
603	      const load = 1.15 - 0.4 * a;
604	      this.drop(
605	        {
606	          ...ink,
607	          x: from.x + (to.x - from.x) * a,
608	          y: from.y + (to.y - from.y) * a,
609	          toX: from.x + (to.x - from.x) * b,
610	          toY: from.y + (to.y - from.y) * b,
611	          water: ink.water * load,
612	          pigment: ink.pigment * load,
613	        },
614	        delayMs + i * (durationMs / steps),
615	      );
616	    }
617	  }
618	
619	  /**
620	   * Seed a rectangle with drops that spread and merge, staggered so the
621	   * wet front arrives across it rather than all at once.
622	   */
623	  bleed(
624	    rect: { x: number; y: number; width: number; height: number },
625	    options: {
626	      seeds?: number;
627	      durationMs?: number;
628	      delayMs?: number;
629	      water?: number;
630	      pigment?: number;
631	    } = {},
632	  ): void {
633	    const seeds =
634	      options.seeds ??
635	      Math.max(3, Math.round(rect.width / (rect.height * 0.9)));
636	    const duration = options.durationMs ?? 260;
637	    const delay = options.delayMs ?? 0;
638	    const radius = rect.height * 0.55;
639	    for (let i = 0; i < seeds; i++) {
640	      const t = (i + 0.5) / seeds;
641	      this.drop(
642	        {
643	          x: rect.x + rect.width * t + (Math.random() - 0.5) * radius * 0.6,
644	          y: rect.y + rect.height * (0.4 + Math.random() * 0.25),
645	          radius: radius * (0.85 + Math.random() * 0.4),
646	          water: options.water ?? 1.1,
647	          pigment: options.pigment ?? 0.16,
648	          ragged: 0.6,
649	        },
650	        delay + t * duration,
651	      );
652	    }
653	  }
654	
655	  splatter(s: InkSplatter): void {
656	    if (this.dead || !this.fields) return;
657	    const cell = this.tuning.cellPx;
658	    const count = Math.min(s.count, MAX_DROPLETS);
659	    const data = new Float32Array(count * DROPLET_FLOATS);
660	    const arc = s.arc ?? Math.PI * 2;
661	    const heading = s.heading ?? 0;
662	    for (let i = 0; i < count; i++) {
663	      const angle = heading + (Math.random() - 0.5) * arc;
664	      const speed = (s.speed / cell) * (0.35 + Math.random() ** 1.6 * 1.2);
665	      const o = i * DROPLET_FLOATS;
666	      data[o] = s.x / cell;
667	      data[o + 1] = s.y / cell;
668	      data[o + 2] = Math.cos(angle) * speed;
669	      data[o + 3] = Math.sin(angle) * speed;
670	      data[o + 4] = 0.2 + Math.random() * 0.4;
671	      data[o + 5] = 0.25 + Math.random() * 0.6;
672	      data[o + 6] = (s.mass ?? 0.5) * (0.3 + Math.random() ** 2 * 1.6);
673	      data[o + 7] = 1;
674	    }
675	    // Ring buffer: the newest throw overwrites the oldest droplets.
676	    const first = Math.min(count, MAX_DROPLETS - this.dropletCursor);
677	    const queue = this.engine.device.queue;
678	    queue.writeBuffer(
679	      this.droplets,
680	      this.dropletCursor * DROPLET_FLOATS * 4,
681	      data,
682	      0,
683	      first * DROPLET_FLOATS,
684	    );
685	    if (first < count) {
686	      queue.writeBuffer(
687	        this.droplets,
688	        0,
689	        data,
690	        first * DROPLET_FLOATS,
691	        (count - first) * DROPLET_FLOATS,
692	      );
693	    }
694	    this.dropletCursor = (this.dropletCursor + count) % MAX_DROPLETS;
695	    this.dropletsUntil = performance.now() + 1500;
696	    this.touch();
697	  }
