788	  private allocate(): void {
789	    const device = this.engine.device;
790	    this.fields?.forEach((t) => t.destroy());
791	    this.splat?.destroy();
792	    const make = (label: string) =>
793	      device.createTexture({
794	        label,
795	        size: [this.cols, this.rows],
796	        format: "rgba16float",
797	        usage:
798	          GPUTextureUsage.STORAGE_BINDING |
799	          GPUTextureUsage.TEXTURE_BINDING |
800	          GPUTextureUsage.COPY_DST,
801	      });
802	    this.fields = [make("ink field a"), make("ink field b")];
803	    this.current = 0;
804	    this.splat = device.createBuffer({
805	      size: this.cols * this.rows * 4,
806	      usage: GPUBufferUsage.STORAGE | GPUBufferUsage.COPY_DST,
807	    });
808	    const views = this.fields.map((t) => t.createView());
809	    const simLayout = this.engine.simPipeline.getBindGroupLayout(0);
810	    const fiberView = this.engine.fibers.createView();
811	    this.simGroups = [0, 1].map((from) =>
812	      [this.quietParams, this.simParams].map((params) =>
813	        device.createBindGroup({
814	          layout: simLayout,
815	          entries: [
816	            { binding: 0, resource: views[from] },
817	            { binding: 1, resource: views[1 - from] },
818	            { binding: 2, resource: fiberView },
819	            { binding: 3, resource: { buffer: params } },
820	            { binding: 4, resource: { buffer: this.dropBuffer } },
821	            { binding: 5, resource: { buffer: this.splat! } },
822	          ],
823	        }),
824	      ),
825	    );
826	    const renderLayout = this.engine.renderPipeline.getBindGroupLayout(0);
827	    this.renderGroups = [0, 1].map((i) =>
828	      device.createBindGroup({
829	        layout: renderLayout,
830	        entries: [
831	          { binding: 0, resource: views[i] },
832	          { binding: 1, resource: this.engine.fieldSampler },
833	          { binding: 2, resource: fiberView },
834	          { binding: 3, resource: this.engine.fiberSampler },
835	          { binding: 4, resource: { buffer: this.renderParams } },
836	        ],
837	      }),
838	    );
839	    this.splatterGroup = device.createBindGroup({
840	      layout: this.engine.splatterPipeline.getBindGroupLayout(0),
841	      entries: [
842	        { binding: 0, resource: { buffer: this.droplets } },
843	        { binding: 1, resource: { buffer: this.splat } },
844	        { binding: 2, resource: { buffer: this.splatterParams } },
845	      ],
846	    });
847	    // Old droplets would land in the wrong place on a new grid.
848	    device.queue.writeBuffer(
849	      this.droplets,
850	      0,
851	      new Float32Array(MAX_DROPLETS * DROPLET_FLOATS),
852	    );
853	  }
854	
855	  private writeSimParams(buffer: GPUBuffer, dropCount: number): void {
856	    const t = this.tuning;
857	    const raw = new ArrayBuffer(64);
858	    const u = new Uint32Array(raw);
859	    const f = new Float32Array(raw);
860	    u[0] = this.cols;
861	    u[1] = this.rows;
862	    u[2] = this.fiberOffset[0];
863	    u[3] = this.fiberOffset[1];
864	    f[4] = t.flow;
865	    f[5] = t.anisotropy;
866	    f[6] = t.absorb;
867	    f[7] = t.evaporation;
868	    f[8] = t.edgeRing;
869	    f[9] = t.fade;
870	    f[10] = t.pin;
871	    f[11] = t.revealAt;
872	    u[12] = dropCount;
873	    f[13] = 1 / MASS_UNITS;
874	    f[14] = t.cellPx;
875	    f[15] = t.carry;
876	    this.engine.device.queue.writeBuffer(buffer, 0, raw);
877	  }
878	
879	  /** @internal */
880	  step(pass: GPUComputePassEncoder, now: number, economy: boolean): void {
881	    if (this.dead || !this.fields) return;
882	    const device = this.engine.device;
883	    if (this.wipe) {
884	      this.wipe = false;
885	      const start =
886	        this.initialField ?? new Uint16Array(this.cols * this.rows * 4);
887	      this.initialField = null;
888	      for (const field of this.fields) {
889	        device.queue.writeTexture(
890	          { texture: field },
891	          start,
892	          { bytesPerRow: this.cols * 8 },
893	          [this.cols, this.rows],
894	        );
895	      }
896	      device.queue.writeBuffer(
897	        this.splat!,
898	        0,
899	        new Uint32Array(this.cols * this.rows),
900	      );
901	    }
902	
903	    if (this.scheduled.length) {
904	      const due = this.scheduled.filter((s) => s.at <= now);
905	      if (due.length) {
906	        this.scheduled = this.scheduled.filter((s) => s.at > now);
907	        this.pending.push(...due.map((s) => s.drop));
908	        this.lastActivity = now;
909	      }
910	    }
911	    const drops = this.pending.splice(0, MAX_DROPS);
912	    const cell = this.tuning.cellPx;
913	    drops.forEach((d, i) => {
914	      const o = i * DROP_FLOATS;
915	      this.dropData[o] = d.x / cell;
916	      this.dropData[o + 1] = d.y / cell;
917	      this.dropData[o + 2] = (d.toX ?? d.x) / cell;
918	      this.dropData[o + 3] = (d.toY ?? d.y) / cell;
919	      this.dropData[o + 4] = Math.max(d.radius / cell, 0.75);
920	      this.dropData[o + 5] = d.water;
921	      this.dropData[o + 6] = d.pigment;
922	      this.dropData[o + 7] = d.ragged ?? 0.4;
923	    });
924	    if (drops.length) {
925	      device.queue.writeBuffer(
926	        this.dropBuffer,
927	        0,
928	        this.dropData,
929	        0,
930	        drops.length * DROP_FLOATS,
931	      );
932	    }
933	    this.writeSimParams(this.simParams, drops.length);
934	    this.writeSimParams(this.quietParams, 0);
935	
936	    if (now < this.dropletsUntil) {
937	      const raw = new ArrayBuffer(32);
938	      const u = new Uint32Array(raw);
939	      const f = new Float32Array(raw);
940	      u[0] = this.cols;
941	      u[1] = this.rows;
942	      u[2] = MAX_DROPLETS;
943	      f[3] = 0.045; // gravity, in launch heights per frame²
944	      f[4] = 0.9; // air drag
945	      device.queue.writeBuffer(this.splatterParams, 0, raw);
946	      pass.setPipeline(this.engine.splatterPipeline);
947	      pass.setBindGroup(0, this.splatterGroup!);
948	      pass.dispatchWorkgroups(Math.ceil(MAX_DROPLETS / 64));
949	    }
950	
951	    const substeps = economy ? 1 : this.tuning.substeps;
952	    pass.setPipeline(this.engine.simPipeline);
953	    for (let k = 0; k < substeps; k++) {
954	      const withDrops = k === 0 && drops.length > 0 ? 1 : 0;
955	      pass.setBindGroup(0, this.simGroups[this.current][withDrops]);
956	      pass.dispatchWorkgroups(
957	        Math.ceil(this.cols / 8),
958	        Math.ceil(this.rows / 8),
959	      );
960	      this.current = 1 - this.current;
961	    }
962	  }
963	
964	  /** @internal */
965	  render(
966	    encoder: GPUCommandEncoder,
967	    now: number,
968	    timestamps: GPUQuerySet | null,
969	  ): void {
970	    if (this.dead || !this.fields) return;
971	    const sleeping = this.asleep(now);
972	    const raw = new Float32Array(24);
973	    raw.set(this.paper.map(srgbToLinear), 0);
974	    raw[3] = this.tuning.strength;
975	    raw.set(this.ink.map(srgbToLinear), 4);
976	    raw[7] = this.tuning.sheen;
977	    raw.set(this.cover.map(srgbToLinear), 8);
978	    raw[11] = this.revealing && !sleeping ? 1 : 0;
979	    raw[12] = 1 / this.cols;
980	    raw[13] = 1 / this.rows;
981	    raw[14] = this.cssWidth / FIBER_SIZE;
982	    raw[15] = this.cssHeight / FIBER_SIZE;
983	    raw[16] = this.fiberOffset[0] / FIBER_SIZE;
984	    raw[17] = this.fiberOffset[1] / FIBER_SIZE;
985	    raw[18] = this.dark ? 1 : 0;
986	    raw[19] = this.tuning.grain;
987	    // A cover lifts by the end of the surface's life even where ink never
988	    // reached, so nothing beneath stays hidden.
989	    const age = now - this.revealStarted;
990	    const life = this.tuning.lifetimeMs;
991	    raw[20] = Math.min(1, Math.max(0, (age - life * 0.45) / (life * 0.35)));
992	    this.engine.device.queue.writeBuffer(this.renderParams, 0, raw);
993	
994	    const pass = encoder.beginRenderPass({
995	      colorAttachments: [
996	        {
997	          view: this.context.getCurrentTexture().createView(),
998	          clearValue: { r: 0, g: 0, b: 0, a: 0 },
999	          loadOp: "clear",
1000	          storeOp: "store",
1001	        },
1002	      ],
1003	      timestampWrites: timestamps
1004	        ? { querySet: timestamps, endOfPassWriteIndex: 1 }
1005	        : undefined,
1006	    });
1007	    // The last frame of a surface only clears it.
1008	    if (!sleeping) {
1009	      pass.setPipeline(this.engine.renderPipeline);
1010	      pass.setBindGroup(0, this.renderGroups[this.current]);
1011	      pass.draw(3);
1012	    }
1013	    pass.end();
1014	    if (this.revealing && this.onPresented) {
1015	      const presented = this.onPresented;
1016	      this.onPresented = null;
1017	      requestAnimationFrame(() => presented());
1018	    }
1019	    if (sleeping) {
1020	      this.revealing = false;
1021	      this.wipe = true;
1022	    }
1023	  }
1024	
1025	  /** @internal */
1026	  asleep(now: number): boolean {
1027	    return (
1028	      this.dead ||
1029	      (this.pending.length === 0 &&
1030	        this.scheduled.length === 0 &&
1031	        now > this.dropletsUntil &&
1032	        now - this.lastActivity > this.tuning.lifetimeMs)
1033	    );
1034	  }
1035	}
1036	
1037	/** Resolve any CSS colour (custom properties included) to sRGB 0..1. */
1038	export function resolveCssColor(el: Element, value: string): Rgb | null {
1039	  const probe = document.createElement("span");
1040	  probe.style.color = value;
1041	  probe.style.display = "none";
1042	  el.appendChild(probe);
1043	  const rgb = parseComputedRgb(getComputedStyle(probe).color);
1044	  probe.remove();
1045	  return rgb;
1046	}
1047	
1048	/** The first opaque background at or behind `el`: the page it sits on. */
1049	export function backgroundBehind(el: Element): Rgb {
1050	  for (let node: Element | null = el; node; node = node.parentElement) {
1051	    const rgb = parseComputedRgb(getComputedStyle(node).backgroundColor);
1052	    if (rgb) return rgb;
1053	  }
1054	  return resolveCssColor(el, "var(--color-paper)") ?? [0.96, 0.93, 0.85];
1055	}
