/** The margin empties, and the proof is stamped clean. */
export const CleanProofDemo = component$<{ ink: boolean; replay: number }>(
  (props) => {
    const state = useStore({ open: NOTES.length, stamped: 0 });
    // eslint-disable-next-line qwik/no-use-visible-task
    useVisibleTask$(async ({ track, cleanup }) => {
      track(() => props.replay);
      let stopped = false;
      cleanup(() => {
        stopped = true;
      });
      // Resolves false once a replay has superseded this run.
      const wait = (ms: number) =>
        new Promise<boolean>((resolve) =>
          setTimeout(() => resolve(!stopped), ms),
        );
      state.open = NOTES.length;
      state.stamped = 0;
      if (!(await wait(600))) return;
      for (let i = NOTES.length; i > 0; i--) {
        state.open = i - 1;
        if (!(await wait(380))) return;
      }
      state.stamped = props.replay + 1;
    });
    return (
      <div class="paper-sheet relative grid min-h-[13rem] grid-cols-[1fr_9rem] gap-4 overflow-hidden px-6 py-5">
        <p
          class="text-[1.05rem] leading-[1.8]"
          style="font-family: var(--font-serif)"
        >
          The ferry left at dawn, and by the time the fog lifted the harbour was
          a rumour behind us.
        </p>
        <div class="relative">
          {NOTES.map((note, i) => (
            <p
              key={note}
              class="mb-2 rounded-sm border border-[color:var(--color-paper-3)] bg-[color:var(--color-paper-soft)] px-2 py-1 text-xs transition-all duration-300"
              style={{
                opacity: i < state.open ? 1 : 0,
                transform: i < state.open ? "none" : "translateX(1.5rem)",
              }}
            >
              {note}
            </p>
          ))}
          <div class="absolute left-1/2 top-1/2 -translate-x-1/2 -translate-y-1/2">
            {state.stamped > 0 && (
              <CleanProofMoment
                key={state.stamped}
                impressionKey={state.stamped}
                ink={props.ink}
              />
            )}
          </div>
        </div>
      </div>
    );
  },
);

