  destroy(): void {
    if (this.dead) return;
    this.dead = true;
    this.engine.forget(this);
    this.fields?.forEach((t) => t.destroy());
    for (const buffer of [
      this.splat,
      this.simParams,
      this.quietParams,
      this.renderParams,
      this.dropBuffer,
      this.droplets,
