699	  /**
700	   * Start a reveal: what lies beneath `rects` (CSS px, surface-relative;
701	   * the whole surface if omitted) is covered until ink soaks through.
702	   */
703	  beginReveal(
704	    rects?: { x: number; y: number; width: number; height: number }[],
705	  ): void {
706	    if (this.dead || !this.fields) return;
707	    this.revealing = true;
708	    this.revealStarted = performance.now();
709	    this.wipe = true;
710	    if (rects) {
711	      // Everything starts revealed except inside the rects, whose cover
712	      // feathers out over a few pixels so it never reads as a box.
713	      const cell = this.tuning.cellPx;
714	      const feather = Math.max(1, 3 / cell);
715	      const covered = new Float32Array(this.cols * this.rows);
716	      for (const r of rects) {
717	        const x0 = r.x / cell;
718	        const y0 = r.y / cell;
719	        const x1 = (r.x + r.width) / cell;
720	        const y1 = (r.y + r.height) / cell;
721	        for (
722	          let y = Math.max(0, Math.floor(y0 - feather));
723	          y < Math.min(this.rows, Math.ceil(y1 + feather));
724	          y++
725	        ) {
726	          const dy = Math.max(y0 - (y + 0.5), y + 0.5 - y1, 0);
727	          for (
728	            let x = Math.max(0, Math.floor(x0 - feather));
729	            x < Math.min(this.cols, Math.ceil(x1 + feather));
730	            x++
731	          ) {
732	            const dx = Math.max(x0 - (x + 0.5), x + 0.5 - x1, 0);
733	            const inside = 1 - Math.min(1, Math.hypot(dx, dy) / feather);
734	            const i = y * this.cols + x;
735	            covered[i] = Math.max(covered[i], inside);
736	          }
737	        }
738	      }
739	      const field = new Uint16Array(this.cols * this.rows * 4);
740	      covered.forEach((c, i) => (field[i * 4 + 3] = toHalf(1 - c)));
741	      this.initialField = field;
742	    }
743	    this.touch();
744	  }
