746	  /** Dry everything at once. */
747	  clear(): void {
748	    this.pending = [];
749	    this.scheduled = [];
750	    this.revealing = false;
751	    this.wipe = true;
752	    this.touch();
753	  }
754	
755	  destroy(): void {
756	    if (this.dead) return;
757	    this.dead = true;
758	    this.engine.forget(this);
759	    this.fields?.forEach((t) => t.destroy());
760	    for (const buffer of [
761	      this.splat,
762	      this.simParams,
763	      this.quietParams,
764	      this.renderParams,
765	      this.dropBuffer,
766	      this.droplets,
