949	    }
950	
951	    const substeps = economy ? 1 : this.tuning.substeps;
952	    pass.setPipeline(this.engine.simPipeline);
953	    for (let k = 0; k < substeps; k++) {
954	      const withDrops = k === 0 && drops.length > 0 ? 1 : 0;
955	      pass.setBindGroup(0, this.simGroups[this.current][withDrops]);
956	      pass.dispatchWorkgroups(
957	        Math.ceil(this.cols / 8),
958	        Math.ceil(this.rows / 8),
959	      );
960	      this.current = 1 - this.current;
961	    }
