56	fn main(@builtin(global_invocation_id) id: vec3u) {
57	  let dims = vec2i(i32(params.width), i32(params.height));
58	  let c = vec2i(id.xy);
59	  if (c.x >= dims.x || c.y >= dims.y) {
60	    return;
