661	  splatter(s: InkSplatter): void {
662	    if (this.dead || !this.fields) return;
663	    const cell = this.tuning.cellPx;
664	    const count = Math.min(s.count, MAX_DROPLETS);
665	    const data = new Float32Array(count * DROPLET_FLOATS);
666	    const arc = s.arc ?? Math.PI * 2;
667	    const heading = s.heading ?? 0;
668	    for (let i = 0; i < count; i++) {
669	      const angle = heading + (Math.random() - 0.5) * arc;
670	      const speed = (s.speed / cell) * (0.35 + Math.random() ** 1.6 * 1.2);
671	      const o = i * DROPLET_FLOATS;
672	      data[o] = s.x / cell;
673	      data[o + 1] = s.y / cell;
674	      data[o + 2] = Math.cos(angle) * speed;
675	      data[o + 3] = Math.sin(angle) * speed;
676	      data[o + 4] = 0.2 + Math.random() * 0.4;
677	      data[o + 5] = 0.25 + Math.random() * 0.6;
678	      data[o + 6] = (s.mass ?? 0.5) * (0.3 + Math.random() ** 2 * 1.6);
679	      data[o + 7] = 1;
680	    }
681	    // Ring buffer: the newest throw overwrites the oldest droplets.
682	    const first = Math.min(count, MAX_DROPLETS - this.dropletCursor);
683	    const queue = this.engine.device.queue;
684	    queue.writeBuffer(
685	      this.droplets,
