919	    drops.forEach((d, i) => {
920	      const o = i * DROP_FLOATS;
921	      this.dropData[o] = d.x / cell;
922	      this.dropData[o + 1] = d.y / cell;
923	      this.dropData[o + 2] = (d.toX ?? d.x) / cell;
924	      this.dropData[o + 3] = (d.toY ?? d.y) / cell;
925	      this.dropData[o + 4] = Math.max(d.radius / cell, 0.75);
926	      this.dropData[o + 5] = d.water;
927	      this.dropData[o + 6] = d.pigment;
