 * A stamp's print: one contact, no flow. It draws only while the die comes
 * down and the ink dries, then keeps its last frame on the canvas.
 */
export class StampPrint implements InkLayer {
  private readonly context: GPUCanvasContext;
  private readonly die: GPUTexture;
  private readonly params: GPUBuffer;
  private readonly group: GPUBindGroup;
  private readonly size: [number, number];
  private readonly ratio: number;
  private readonly fiberOffset = [Math.random(), Math.random()];
  private paper: Rgb = [0.98, 0.96, 0.9];
  private ink: Rgb = [0.85, 0.25, 0.15];
  private dark = false;
  private contact = 0;
  private pressed = false;
  private dead = false;
  private heavy: [number, number] = [1, 0];
  private lean = 0.4;
  private load = 1;
  private seed: [number, number] = [0, 0];
