    style={{
      "--workflow-stamp-image": `url("/assets/rubric-stamps/sunburst-${props.kind}.png")`,
    }}
  >
    <StampPress
      key={props.impressionKey ?? props.kind}
      animated={props.animated ?? true}
    >
      <span class="workflow-stamp__mark" />
    </StampPress>
  </span>
));
